fn frombuffer(buffer: &Vec<u8>, count: usize, offset: usize) -> Vec<u8> {
    // Since we assume offset + count <= buffer.len(), the slice is always in-bounds.
    // Taking a slice and converting it to a Vec<u8> gives us a new array
    // containing exactly `count` bytes starting from `offset`.
    buffer[offset..offset + count].to_vec()
}

